#!/usr/bin/env python3
"""Raw byte-level prober: write exact bytes to rustowl stdin, capture exact stdout/stderr bytes."""
import os, subprocess, sys, time, threading

BIN = os.environ.get("RUSTOWL_BIN", "/workspace/executable")

class Raw:
    def __init__(self, args=None, cwd=None, env=None):
        args = args if args is not None else ["--stdio"]
        e = dict(os.environ)
        e["HOME"] = "/tmp/home-lspcore"
        if env:
            e.update(env)
        self.p = subprocess.Popen([BIN]+args, stdin=subprocess.PIPE,
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                  cwd=cwd, env=e, bufsize=0)
        self.out = bytearray()
        self.errb = bytearray()
        self.lock = threading.Lock()
        threading.Thread(target=self._pump, args=(self.p.stdout, self.out), daemon=True).start()
        threading.Thread(target=self._pump, args=(self.p.stderr, self.errb), daemon=True).start()

    def _pump(self, f, buf):
        while True:
            b = f.read(1)
            if not b:
                return
            with self.lock:
                buf += b

    def w(self, data: bytes):
        try:
            self.p.stdin.write(data)
            self.p.stdin.flush()
        except Exception as ex:
            return repr(ex)
        return None

    def frame(self, body: bytes):
        return self.w(b"Content-Length: %d\r\n\r\n" % len(body) + body)

    def outb(self):
        with self.lock:
            return bytes(self.out)

    def eb(self):
        with self.lock:
            return bytes(self.errb)

    def wait_out(self, n=1, timeout=5.0):
        """wait until stdout has grown to >= n bytes or timeout"""
        end = time.time()+timeout
        while time.time() < end:
            if len(self.outb()) >= n:
                return True
            time.sleep(0.03)
        return False

    def wait_grow(self, timeout=3.0, quiet=0.4):
        """wait until stdout stops growing for `quiet` seconds (or timeout)"""
        end = time.time()+timeout
        last = len(self.outb()); lastch = time.time()
        while time.time() < end:
            time.sleep(0.05)
            cur = len(self.outb())
            if cur != last:
                last = cur; lastch = time.time()
            elif time.time()-lastch > quiet and cur > 0:
                return
        return

    def closein(self):
        try: self.p.stdin.close()
        except Exception: pass

    def wait(self, timeout=6):
        try:
            return self.p.wait(timeout)
        except Exception:
            self.p.kill()
            try: self.p.wait(3)
            except Exception: pass
            return "TIMEOUT/KILLED rc=%r" % self.p.returncode

    def alive(self):
        return self.p.poll() is None

def msg(**kw):
    import json
    return json.dumps(kw, separators=(",", ":")).encode()

def show(tag, r, rc=None):
    print("=== %s ===" % tag)
    print("STDOUT bytes: %r" % r.outb())
    e = r.eb().decode("utf8","replace")
    print("STDERR: %r" % e)
    if rc is not None:
        print("EXIT: %r" % rc)
    print()

#!/usr/bin/env python3
"""Frame-aware raw client: keeps raw bytes per response frame."""
import sys, time, json
sys.path.insert(0, '/tmp/lspcore')
from raw import Raw, msg

class FC(Raw):
    def frames(self):
        b = self.outb()
        out = []
        i = 0
        while True:
            j = b.find(b"\r\n\r\n", i)
            if j < 0:
                break
            hdr = b[i:j+4]
            # parse CL (last wins)
            cl = None
            for line in hdr.split(b"\r\n"):
                if line.startswith(b"Content-Length:"):
                    cl = int(line.split(b":",1)[1].strip())
            if cl is None:
                break
            body = b[j+4:j+4+cl]
            if len(body) < cl:
                break
            out.append((hdr, body))
            i = j+4+cl
        return out

    def nframes(self):
        return len(self.frames())

    def wait_frames(self, n, timeout=6.0):
        end = time.time()+timeout
        while time.time() < end:
            if self.nframes() >= n:
                return True
            time.sleep(0.04)
        return False

    def dump(self, label=""):
        print("--- frames %s ---" % label)
        for k,(h,bd) in enumerate(self.frames()):
            print("  [%d] hdr=%r" % (k, h))
            print("  [%d] body=%r" % (k, bd))
        return self.frames()

